package com.example.discovery.provider.config;import java.time.Duration;import org.springframework.boot.context.properties.ConfigurationProperties;@ConfigurationProperties(prefix="service.discovery") public record ProviderProperties(String serviceName,String instanceId,String host,int port,String registryUrl,Duration heartbeatInterval){public ProviderProperties{if(serviceName==null)serviceName="payment-service"; if(port==0)port=8081; if(instanceId==null||instanceId.isBlank())instanceId=serviceName+"-"+port; if(host==null)host="localhost"; if(registryUrl==null)registryUrl="http://localhost:8761"; if(heartbeatInterval==null)heartbeatInterval=Duration.ofSeconds(3);} public String healthUrl(){return "http://"+host+":"+port+"/actuator/health";}}
